// Tag each new post by topic, score engagement, flag standout posts. No posts: stop here.
const TOPICS = {
  launch: /\b(launch(ed|ing)?|introduc(e|ed|ing)|now (available|live|rolling out|supports|open)|rolling out|just dropped|new (model|feature|plan|mode|product)|release[ds]?|announc(e|es|ed|ing)|^new:)/i,
  funding: /\b(raised|funding|series [a-e]|seed round|investors?|valuation|ipo|s-1|acquir(e|ed|es|ing)|acquisition)\b/i,
  hiring: /\b(we('| a)re hiring|hiring|join (our|the) team|open roles?|careers?|is joining|welcome (\w+ )?to the team)\b/i,
  expansion: /\b(new office|opened an office|new hub|expanding (to|access|into)|new (countries|markets|regions?)|coming to (europe|asia|the uk|the us))\b/i,
  event: /\b(webinar|conference|summit|meetup|join us|meet us|booth|keynote|speakers|tickets?|devday|events?)\b/i,
  partnership: /\b(partner(s|ship|ships|ed|ing)?|integration|teamed up|together with|working with)\b/i,
  customer: /\b(customer story|case study|customers?|clients?|how \w+ uses)\b/i,
};
const posts = $input.all().map(i => i.json).filter(p => p.id && p.url);
if (!posts.length) return [];
const scores = posts.map(p => (p.reactions || 0) + 3 * (p.comments || 0)).sort((a, b) => a - b);
const top = scores[Math.floor(scores.length * 0.8)] ?? 0;
return posts.map(p => {
  const text = (p.text || '').replace(/\s+/g, ' ').trim();
  const topics = Object.keys(TOPICS).filter(t => TOPICS[t].test(text));
  const engagement = (p.reactions || 0) + 3 * (p.comments || 0);
  return { json: {
    posted: (p.postedAt || '').slice(0, 10),
    company: p.company || 'Unknown',
    topics: topics.join(', ') || 'other',
    engagement,
    standout: engagement > 0 && engagement >= top ? 'yes' : '',
    reactions: p.reactions ?? 0,
    comments: p.comments ?? 0,
    repost: p.isRepost ? 'yes' : '',
    text: text.slice(0, 500),
    url: p.url,
    company_followers: p.companyFollowers ?? '',
  } };
});

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// One HTML e-mail: topic summary, then each company's posts, most engaging first.
const cfg = $('Configure').first().json;
const posts = $('Tag and score posts').all().map(i => i.json);
const topicCount = {};
for (const p of posts) for (const t of p.topics.split(', ')) topicCount[t] = (topicCount[t] || 0) + 1;
const ranked = Object.entries(topicCount).sort((a, b) => b[1] - a[1]);
const summary = ranked.map(([t, n]) => `${n} ${t}`).join(' · ');
const headline = ranked.filter(([t]) => t !== 'other').slice(0, 3).map(([t, n]) => `${n} ${t}`).join(', ');
const byCompany = {};
for (const p of posts) (byCompany[p.company] ||= []).push(p);
const sections = Object.entries(byCompany)
  .sort((a, b) => Math.max(...b[1].map(p => p.engagement)) - Math.max(...a[1].map(p => p.engagement)))
  .map(([company, list]) => {
    list.sort((a, b) => b.engagement - a.engagement);
    const items = list.map(p => `<li style="margin-bottom:10px">${p.standout ? '<b>★ </b>' : ''}<b>${esc(p.posted)}</b> <i>[${esc(p.topics)}]</i> ${esc(p.text.slice(0, 280))}${p.text.length > 280 ? '…' : ''}<br><small>${p.reactions} reactions · ${p.comments} comments · <a href="${esc(p.url)}">open post</a></small></li>`).join('');
    return `<h3 style="margin:18px 0 6px">${esc(company)} (${list.length})</h3><ul style="padding-left:18px">${items}</ul>`;
  }).join('');
const companies = Object.keys(byCompany).length;
return [{ json: {
  sendTo: cfg.sendTo,
  subject: `${posts.length} new LinkedIn post${posts.length > 1 ? 's' : ''} from ${companies} compan${companies > 1 ? 'ies' : 'y'}${headline ? ` (${headline})` : ''}`,
  html: `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.45"><p><b>This week:</b> ${esc(summary)}. ★ = most engaging posts.</p>${sections}</div>`,
} }];
